    stamp: (a) => { const c = a[1]; const holes = Array.from({ length: 11 }, (_, i) => `<circle cx="${68 + i * 10.4}" cy="30" r="3" fill="var(--hole)"/><circle cx="${68 + i * 10.4}" cy="152" r="3" fill="var(--hole)"/>`).join('') + Array.from({ length: 12 }, (_, i) => `<circle cx="66" cy="${36 + i * 10.4}" r="3" fill="var(--hole)"/><circle cx="174" cy="${36 + i * 10.4}" r="3" fill="var(--hole)"/>`).join(''); return `<rect x="66" y="30" width="108" height="122" fill="#fbf4e4"/>${holes}<rect x="76" y="40" width="88" height="102" fill="${c}"/>${a[2] === 'jenny' ? `<rect x="82" y="46" width="76" height="74" fill="#fbf4e4"/><g transform="rotate(180 120 84)"><path d="M88 84 h64 M104 74 h32 M104 94 h32 M116 74 v20 M146 80 l8 -6 v20 l-8 -6" stroke="#1e3a8a" stroke-width="4"/><circle cx="96" cy="84" r="4" fill="#1e3a8a"/></g><text x="120" y="134" font-size="13" text-anchor="middle" font-weight="900" fill="#fbf4e4" font-family="serif">24 CENTS</text>` : `<path d="M86 96 h68 l-8 14 h-52Z" fill="#1d1d1d"/><path d="M118 96 V58 L142 92Z" fill="#1d1d1d"/><path d="M100 96 V70 L116 94Z" fill="#1d1d1d"/><text x="120" y="132" font-size="10" text-anchor="middle" font-weight="900" fill="#1d1d1d" font-family="serif">ONE CENT</text>`}`; },
